import { mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';

import { DeleteObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';

import type { Config } from '../../config/env.js';

/** Where the re-encoded files go. Keys are generated by the server ("banner/2026/11/<id>.webp"). */
export interface MediaStorage {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** Removes a stored file. A key that is already gone is not an error. */
  delete(key: string): Promise<void>;
  /** Public URL of a stored key. `apiBase`: the API's address the client used (local storage only). */
  url(key: string, apiBase: string): string;
}

const KEY_RE = /^[a-z]+\/\d{4}\/\d{2}\/[a-f0-9]{24}\.(webp|pdf)$/;
/** The type a stored key is served with. */
export const contentTypeOf = (key: string) => (key.endsWith('.pdf') ? 'application/pdf' : 'image/webp');
export const isMediaKey = (key: string) => KEY_RE.test(key);

/** Development: files under MEDIA_DIR, served by the API on /media/<key>. */
export class LocalMediaStorage implements MediaStorage {
  private readonly root: string;
  constructor(dir: string, private readonly publicUrl?: string) {
    this.root = resolve(dir);
  }
  async put(key: string, body: Buffer) {
    const path = join(this.root, key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, body);
  }
  async delete(key: string) {
    if (!isMediaKey(key)) return;
    await unlink(join(this.root, key)).catch((err: NodeJS.ErrnoException) => {
      if (err.code !== 'ENOENT') throw err;
    });
  }
  url(key: string, apiBase: string) {
    return `${this.publicUrl ?? `${apiBase}/media`}/${key}`;
  }
  /** For the /media route; null for anything that isn't a stored key. */
  async read(key: string) {
    if (!isMediaKey(key)) return null;
    return readFile(join(this.root, key)).catch(() => null);
  }
}

/** Production: an S3-compatible bucket (AWS S3, Cloudflare R2), read through MEDIA_PUBLIC_URL (CDN or bucket domain). */
export class S3MediaStorage implements MediaStorage {
  private readonly client: S3Client;
  constructor(private readonly c: Config) {
    this.client = new S3Client({
      region: c.S3_REGION,
      ...(c.S3_ENDPOINT ? { endpoint: c.S3_ENDPOINT } : {}),
      credentials: { accessKeyId: c.S3_ACCESS_KEY_ID ?? '', secretAccessKey: c.S3_SECRET_ACCESS_KEY ?? '' },
    });
  }
  async put(key: string, body: Buffer, contentType: string) {
    // Never changes once written (the key is unique): cached for a year.
    await this.client.send(new PutObjectCommand({ Bucket: this.c.S3_BUCKET, Key: key, Body: body, ContentType: contentType, CacheControl: 'public, max-age=31536000, immutable' }));
  }
  async delete(key: string) {
    // S3 and R2 answer a delete of a missing key with success.
    await this.client.send(new DeleteObjectCommand({ Bucket: this.c.S3_BUCKET, Key: key }));
  }
  url(key: string) {
    return `${this.c.MEDIA_PUBLIC_URL}/${key}`;
  }
}

export function createMediaStorage(c: Config): MediaStorage {
  return c.MEDIA_STORAGE === 's3' ? new S3MediaStorage(c) : new LocalMediaStorage(c.MEDIA_DIR, c.MEDIA_PUBLIC_URL);
}
